for f in select id,stable_code from public.food_items where owner_id is null and stable_code is not null loop
 encoded:=replace(encoded,to_json('catalog:'||f.stable_code)::text,to_json(f.id::text)::text);
end loop;
if position('"catalog:' in encoded)>0 then raise exception 'Falta un alimento del catálogo requerido por la importación'; end if;
with seed as (select encoded::jsonb as c), expanded as (select jsonb_set(jsonb_set(c,'{menu,menus,0,meal_menus}',(select jsonb_agg(jsonb_build_object('meal_time_id',o->'meal_time_id','entries',o->'entries')) from jsonb_array_elements(c#>'{menu,meal_options}') o)),'{menu,week_plan,days,0,assignments}',(select jsonb_agg(jsonb_build_object('meal_time_id',o->'meal_time_id','option_id',o->'id','option_snapshot',o,'fixed',false)) from jsonb_array_elements(c#>'{menu,meal_options}') o)) as content from seed) update public.diet_library_items as library set name='Huevos, res y tostadas de atún · 2046 kcal',content=expanded.content,provenance='{"kind":"provided_pdf","source_key":"PDF03-D2","import_version":2,"label":"Colección de cocina cotidiana · Nuthrick","target_basis":"Aportes aproximados calculados por equivalentes. Los objetivos de referencia usan energía 4/4/9; no son la meta declarada en el documento.","notes":["Dieta de un día editable. Revisar ingredientes, porciones y adecuación al paciente.","No se añade aceite ni azúcar que no figure en los ingredientes o con cantidad explícita en la preparación. Las verduras mixtas incluyen la guarnición; condimentos sin cantidad no se contabilizan por separado."]}'::jsonb from expanded where owner_id is null and provenance->>'kind'='provided_pdf' and (provenance->>'source_key'='PDF03-D2' or split_part(provenance->>'label',' · ',2)='PDF03-D2') and (provenance->>'import_version') is distinct from '2';
